#!/usr/bin/env python3
"""Join our greedy/beam-search/Pourfecto results (run on instances generated by
generate_table2_instances.py) against Table 2 of Ferdosi, Ge & Kingsford, WABI 2023, transcribed
verbatim from the published paper.

Sample sizes matched to the paper's own methodology: greedy and Pourfecto use all 1000 generated
instances per config; beam search uses only the first 100 (sorted by instance name) -- the paper's
own Table 2 also used 1000 reps for RL/GH but only 100 for BS, since it is far slower.

Output: results/table2_comparison.csv, plus a printed markdown table for the paper supplement.
"""
import argparse
import csv
import glob
import os
import statistics

# Transcribed verbatim from Table 2 of the WABI 2023 paper (page 23:12).
PAPER_TABLE2 = {
    "4x4_4-4":       {"grid": "4x4",   "reagents": "4,4",       "RL": (100.0, 38.496, "22m",  0.484),
                       "GH": (78.7, 39.40, None, 0.004), "BS": (95.0, 23.87, None, 3.80)},
    "6x6_3-3":       {"grid": "6x6",   "reagents": "3,3",       "RL": (100.0, 44.471, "50m",  0.484),
                       "GH": (93.2, 46.254, None, 0.002), "BS": (92.0, 30.74, None, 5.37)},
    "6x6_8-8":       {"grid": "6x6",   "reagents": "8,8",       "RL": (98.9, 102.84, "1h 21m", 0.490),
                       "GH": (59.8, 113.148, None, 0.009), "BS": (72.0, 68.44, None, 30.10)},
    "8x8_4-4":       {"grid": "8x8",   "reagents": "4,4",       "RL": (100.0, 76.53, "1h 51m", 0.486),
                       "GH": (93.0, 81.455, None, 0.003), "BS": (91.0, 59.59, None, 24.67)},
    "8x8_15-15":     {"grid": "8x8",   "reagents": "15,15",     "RL": (95.3, 264.97, "4h 31m", 0.494),
                       "GH": (40.0, 266.652, None, 0.014), "BS": (43.0, 190.08, None, 143.47)},
    "10x10_5-5-5-5": {"grid": "10x10", "reagents": "5,5,5,5",   "RL": (87.9, 232.83, "6h 36m", 0.474),
                       "GH": (70.5, 249.99, None, 0.008), "BS": (34.0, 150.41, None, 306.45)},
}
CONFIG_ORDER = ["4x4_4-4", "6x6_3-3", "6x6_8-8", "8x8_4-4", "8x8_15-15", "10x10_5-5-5-5"]


def read_csv(path):
    if not os.path.exists(path):
        return []
    with open(path) as f:
        return list(csv.DictReader(f))


def to_num(v):
    try:
        return float(v)
    except (TypeError, ValueError):
        return None


def aggregate_restart_style(rows):
    """For greedy/beam_search rows (success_rate, mean_distance, mean_wall_time_s per instance,
    restarts=1): success% over all rows, mean distance among successes, mean query time overall."""
    if not rows:
        return None
    success_rate = 100.0 * sum(to_num(r["success_rate"]) or 0.0 for r in rows) / len(rows)
    distances = [to_num(r["mean_distance"]) for r in rows]
    distances = [d for d in distances if d is not None]
    mean_distance = sum(distances) / len(distances) if distances else None
    times = [to_num(r["mean_wall_time_s"]) for r in rows]
    times = [t for t in times if t is not None]
    mean_time = sum(times) / len(times) if times else None
    return success_rate, mean_distance, mean_time, len(rows)


def aggregate_pourfecto(rows):
    if not rows:
        return None
    def is_true(v):
        return str(v).strip().lower() in ("true", "1")
    success_rate = 100.0 * sum(1 for r in rows if is_true(r["success"])) / len(rows)
    distances = [to_num(r["distance"]) for r in rows if is_true(r["success"])]
    distances = [d for d in distances if d is not None]
    mean_distance = sum(distances) / len(distances) if distances else None
    times = [to_num(r["wall_time_s"]) for r in rows]
    times = [t for t in times if t is not None]
    mean_time = sum(times) / len(times) if times else None
    return success_rate, mean_distance, mean_time, len(rows)


def fmt(v, digits=1):
    return f"{v:.{digits}f}" if v is not None else "-"


def main():
    ap = argparse.ArgumentParser(description=__doc__)
    ap.add_argument("--results-dir", default=os.path.join(os.path.dirname(__file__), "results"))
    ap.add_argument("--out", default=os.path.join(os.path.dirname(__file__), "results", "table2_comparison.csv"))
    args = ap.parse_args()

    out_rows = []
    for cfg in CONFIG_ORDER:
        paper = PAPER_TABLE2[cfg]

        greedy_rows = read_csv(os.path.join(args.results_dir, f"greedy_{cfg}.csv"))
        greedy_agg = aggregate_restart_style(greedy_rows)

        bs_rows = read_csv(os.path.join(args.results_dir, f"beam_search_{cfg}.csv"))
        bs_rows_sorted = sorted(bs_rows, key=lambda r: r["instance"])[:100]  # match paper's n=100 for BS
        bs_agg = aggregate_restart_style(bs_rows_sorted)

        pf_rows = read_csv(os.path.join(args.results_dir, f"pourfecto_{cfg}.csv"))
        pf_agg = aggregate_pourfecto(pf_rows)

        row = {
            "config": cfg, "grid": paper["grid"], "reagents": paper["reagents"],
            "RL_success_pct_paper": paper["RL"][0], "RL_distance_paper": paper["RL"][1],
            "RL_query_s_paper": paper["RL"][3],
            "GH_success_pct_paper": paper["GH"][0], "GH_distance_paper": paper["GH"][1],
            "GH_query_s_paper": paper["GH"][3],
            "BS_success_pct_paper": paper["BS"][0], "BS_distance_paper": paper["BS"][1],
            "BS_query_s_paper": paper["BS"][3],
        }
        if greedy_agg:
            row["GH_success_pct_ours"], row["GH_distance_ours"], row["GH_query_s_ours"], row["GH_n"] = greedy_agg
        if bs_agg:
            row["BS_success_pct_ours"], row["BS_distance_ours"], row["BS_query_s_ours"], row["BS_n"] = bs_agg
        if pf_agg:
            row["Pourfecto_success_pct"], row["Pourfecto_distance"], row["Pourfecto_query_s"], row["Pourfecto_n"] = pf_agg
        out_rows.append(row)

    os.makedirs(os.path.dirname(args.out), exist_ok=True)
    fieldnames = list(out_rows[0].keys())
    for r in out_rows:
        for k in fieldnames:
            r.setdefault(k, "")
    with open(args.out, "w", newline="") as f:
        writer = csv.DictWriter(f, fieldnames=fieldnames)
        writer.writeheader()
        writer.writerows(out_rows)
    print(f"wrote {args.out}\n")

    # Standalone per-metric tables (CSV + markdown), for direct inclusion in the paper supplement --
    # each combines the paper's published RL/GH/BS numbers, our own GH/BS reproduction, and
    # Pourfecto's result for one metric.
    header = ["Grid", "Reagents", "RL (paper)", "GH (paper)", "GH (this work)", "BS (paper)", "BS (this work)", "Pourfecto (this work)"]

    def build_metric_table(title, field_prefix, digits, note=""):
        rows = []
        for cfg, r in zip(CONFIG_ORDER, out_rows):
            rows.append([
                r["grid"], r["reagents"],
                fmt(r[f"RL_{field_prefix}_paper"], digits), fmt(r[f"GH_{field_prefix}_paper"], digits),
                fmt(r.get(f"GH_{field_prefix}_ours"), digits), fmt(r[f"BS_{field_prefix}_paper"], digits),
                fmt(r.get(f"BS_{field_prefix}_ours"), digits), fmt(r.get(f"Pourfecto_{field_prefix}"), digits),
            ])
        return title, rows, note

    def write_metric_table(title, slug, rows, note=""):
        csv_path = os.path.join(os.path.dirname(args.out), f"{slug}.csv")
        with open(csv_path, "w", newline="") as f:
            writer = csv.writer(f)
            writer.writerow(header)
            writer.writerows(rows)
        print(f"wrote {csv_path}")

        md_path = os.path.join(os.path.dirname(args.out), f"{slug}.md")
        with open(md_path, "w") as f:
            f.write(f"# Table 2 reproduction: {title}\n\n")
            f.write("Ferdosi, Ge & Kingsford (WABI 2023) Table 2 vs. this benchmark's reproduction.\n\n")
            if note:
                f.write(note + "\n\n")
            f.write("| " + " | ".join(header) + " |\n")
            f.write("|" + "---|" * len(header) + "\n")
            for row in rows:
                f.write("| " + " | ".join(row) + " |\n")
        print(f"wrote {md_path}\n")

    def print_metric_table(title, rows, note=""):
        print(f"### {title}\n")
        if note:
            print(note + "\n")
        print("| " + " | ".join(header) + " |")
        print("|" + "---|" * len(header))
        for row in rows:
            print("| " + " | ".join(row) + " |")
        print()

    metric_tables = [
        build_metric_table("success rate (%)", "success_pct", 1),
        build_metric_table("mean distance cost (successful runs)", "distance", 1),
        build_metric_table("mean query time (seconds)", "query_s", 4,
                            note="RL training time omitted (22m-6h36m per config in the paper; see README)."),
    ]
    slugs = ["success_rate_table", "distance_table", "query_time_table"]
    for (title, rows, note), slug in zip(metric_tables, slugs):
        write_metric_table(title, slug, rows, note)
    for title, rows, note in metric_tables:
        print_metric_table(title, rows, note)

    write_latex_table(out_rows, os.path.join(os.path.dirname(args.out), "table2_full_comparison.tex"))


def tex_escape(s):
    return str(s).replace("_", r"\_")


def write_latex_table(out_rows, path):
    """Single publication-ready LaTeX table, laid out like Table 2 of the paper itself (M x N |
    Reagents | Model | Success Rate(%) | Distance Cost | Training time | Query(s), grouped by
    config with \\multirow spanning each config's model rows) -- extended with our GH/BS
    reproduction and Pourfecto as additional model rows per config."""

    def tex_fmt(v, digits):
        return fmt(v, digits).replace("-", "--") if v is None else fmt(v, digits)

    def model_row(model, success, distance, training, query):
        return (model, tex_fmt(success, 1), tex_fmt(distance, 1), training if training else "--", tex_fmt(query, 4))

    lines = []
    lines.append(r"% Requires: \usepackage{booktabs} \usepackage{multirow}")
    lines.append(r"% 'Ferdosi et al.' rows are transcribed from Table 2 of Ferdosi, Ge & Kingsford (WABI 2023);")
    lines.append(r"% replace that label with \citep{...} as needed. '(this work)' rows are this benchmark's reproduction.")
    lines.append(r"\begin{table}[t]")
    lines.append(r"\centering")
    lines.append(r"\caption{Reproduction of Table~2 (Ferdosi, Ge \& Kingsford, WABI 2023), extended with our "
                 r"greedy-heuristic (GH) and beam-search (BS) reproduction and with Pourfecto. Success rate is "
                 r"the fraction of instances solved exactly; distance cost is the mean Manhattan travel distance "
                 r"among solved instances; query time is the mean wall-clock time to produce one protocol. "
                 r"Pourfecto is deterministic and exact, so it has no training time and 100\% success at every "
                 r"configuration.}")
    lines.append(r"\label{tab:table2-full-comparison}")
    lines.append(r"\begin{tabular}{@{}lllrrlr@{}}")
    lines.append(r"\toprule")
    lines.append(r"$M \times N$ & Reagents & Model & Success Rate(\%) & Distance Cost & Training time & Query(s) \\")
    lines.append(r"\midrule")

    for cfg, r in zip(CONFIG_ORDER, out_rows):
        paper = PAPER_TABLE2[cfg]
        model_rows = [
            # RL and Pourfecto head-to-head first (the two "flagship" methods), then each baseline
            # heuristic's paper-vs-reproduction pair below.
            model_row("RL (Ferdosi et al.)", paper["RL"][0], paper["RL"][1], paper["RL"][2], paper["RL"][3]),
            model_row("Pourfecto (this work)", r.get("Pourfecto_success_pct"), r.get("Pourfecto_distance"), None, r.get("Pourfecto_query_s")),
            model_row("GH (Ferdosi et al.)", paper["GH"][0], paper["GH"][1], None, paper["GH"][3]),
            model_row("GH (this work)", r.get("GH_success_pct_ours"), r.get("GH_distance_ours"), None, r.get("GH_query_s_ours")),
            model_row("BS (Ferdosi et al.)", paper["BS"][0], paper["BS"][1], None, paper["BS"][3]),
            model_row("BS (this work)", r.get("BS_success_pct_ours"), r.get("BS_distance_ours"), None, r.get("BS_query_s_ours")),
        ]
        n_rows = len(model_rows)
        for i, (model, success, distance, training, query) in enumerate(model_rows):
            grid_cell = rf"\multirow{{{n_rows}}}{{*}}{{{tex_escape(r['grid'])}}}" if i == 0 else ""
            reagents_cell = rf"\multirow{{{n_rows}}}{{*}}{{{tex_escape(r['reagents'])}}}" if i == 0 else ""
            lines.append(f"{grid_cell} & {reagents_cell} & {model} & {success} & {distance} & {training} & {query} \\\\")
        lines.append(r"\midrule")

    lines[-1] = r"\bottomrule"  # replace the final \midrule
    lines.append(r"\end{tabular}")
    lines.append(r"\end{table}")

    with open(path, "w") as f:
        f.write("\n".join(lines) + "\n")
    print(f"wrote {path}")


if __name__ == "__main__":
    main()
